# Reference essays and tool-specific FAQs for every GWB tool page.
# Rendered inside the guide column (right of the tool on desktop). Plain-text FAQ
# answers are also copied into FAQPage JSON-LD. Estimates are not professional advice.
import html as _html
import re

def _esc(s):
    return _html.escape(s, quote=True)

def faq_html(qa):
    return ''.join('<h3>'+_esc(q)+'</h3><p>'+_esc(a)+'</p>' for q, a in qa)

def plain(fragment):
    t = re.sub(r'<[^>]+>', ' ', fragment)
    t = t.replace('&amp;', '&').replace('&lt;', '<').replace('&gt;', '>').replace('&quot;', '"').replace('&#x27;', "'")
    return re.sub(r'\s+', ' ', t).strip()

